export function translateFrPhrase(source: string): string {
  return FR_TRANSLATIONS[source] || source;
}

export function translateFrRecord<T extends Record<string, string>>(source: T): T {
  return Object.fromEntries(Object.entries(source).map(([key, value]) => [key, translateFrPhrase(value)])) as T;
}
